// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0) && caller != address(this));
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        vm.deal(caller, amount);
        uint256 preCallerBal = c.getBalance(caller);
        uint256 preZeroBal = c.getBalance(address(0));
        vm.prank(caller);
        try c.addToBalance{value: amount}() { } catch { }
        uint256 postCallerBal = c.getBalance(caller);
        uint256 postZeroBal = c.getBalance(address(0));
        assertTrue(postCallerBal == preCallerBal + amount && postZeroBal == preZeroBal);
    }
}
